const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const query = String(body.query || body.chatInput || body.text || '').trim();

const GRADE_WORDS = {
  prek: -1, 'pre-k': -1, preschool: -1, kindergarten: 0, k: 0,
  first: 1, '1st': 1, second: 2, '2nd': 2, third: 3, '3rd': 3,
  fourth: 4, '4th': 4, fifth: 5, '5th': 5, sixth: 6, '6th': 6,
  seventh: 7, '7th': 7, eighth: 8, '8th': 8,
  ninth: 9, '9th': 9, tenth: 10, eleventh: 11, twelfth: 12,
  'high school': 9, '9-12': 9
};

const lower = query.toLowerCase();
let gradeSort = '';
for (const [word, g] of Object.entries(GRADE_WORDS)) {
  if (lower.includes(word)) { gradeSort = String(g > 9 ? 9 : g); break; }
}
if (gradeSort === '') {
  const ordinal = lower.match(/(\d{1,2})(st|nd|rd|th)?[\s-]*grade/) || lower.match(/\bgrade[\s-]*(\d{1,2})\b/);
  if (ordinal) {
    const n = parseInt(ordinal[1], 10);
    gradeSort = String(n >= 9 ? 9 : n);
  }
}

const stdMatch = query.match(/\b([A-Z]{2}(?:\.\d+){2,3}\.\d+|VPK-SC\.\d+)\b/i);
const standard = stdMatch ? stdMatch[1].toUpperCase() : '';

const STOP = new Set(['the','and','about','find','a','an','lesson','lessons','show','me','what','which','does','align','with','cover','covers','for','who','how','that','this','from','into','near','is','are','to','of','on','in','grade','graders']);
const words = lower.replace(/[^a-z0-9\s.-]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !STOP.has(w));
const topic = words.filter(w => !/^\d+$/.test(w)).slice(0, 6).join(' ');

return [{ json: { query, gradeSort, standard, topic } }];

const rows = $input.all().map(i => i.json);
const parsed = $('Parse Query').first().json;
const catalogSize = rows.length ? Number(rows[0].catalog_size || 0) : 0;

const lessons = rows.filter(r => r && r.lesson_id).map(r => {
  const sort = r.grade_sort == null ? 0 : Number(r.grade_sort);
  const gradeMax = sort === 9 ? 12 : sort;
  const topics = String(r.topic_tags || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
  const standards = String(r.standards_raw || '').split(/[,;]/).map(s => s.trim()).filter(Boolean);
  return {
    id: r.lesson_id,
    title: r.title,
    gradeRange: r.grade_label || '',
    gradeMin: sort,
    gradeMax,
    topics,
    ngsssStandards: standards,
    fundamentalConcept: r.concepts || '',
    summary: r.summary || '',
    lessonUrl: r.lesson_url || '',
    pdfUrl: r.pdf_url || ''
  };
});

let text;
if (!parsed.query) {
  text = 'What would you like to find — a topic, grade level, or standard?';
} else if (lessons.length === 0) {
  text = "I couldn't find a lesson matching that in the Teacher Toolkit. Try naming a topic, grade level, or NGSSS standard.";
} else {
  const lead = lessons.length === 1 ? "Here's a lesson" : `Here are ${lessons.length} lessons`;
  if (parsed.standard) text = `${lead} aligned with ${parsed.standard}:`;
  else if (parsed.gradeSort !== '') {
    const g = Number(parsed.gradeSort);
    const label = g === -1 ? 'PreK' : g === 0 ? 'Kindergarten' : g === 9 ? 'grades 9-12' : `grade ${g}`;
    text = `${lead} for ${label}:`;
  } else text = `${lead} from the Teacher Toolkit:`;
}

return [{ json: {
  text, lessons, source: 'n8n',
  catalogHitCount: lessons.length,
  catalogSize,
  catalogReady: catalogSize > 0
} }];
